158	export async function gameUpdateSweep(): Promise<void> {
159	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
160	  const candidates = await db.server.findMany({
161	    where: {
162	      status: "RUNNING",
163	      autoUpdate: true,
164	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
165	    },
